renderTasks function:

const tasks = loadTasks();

list.innerHTML = '';

tasks.forEach(task => {
    const li = document.createElement('li');
    li.dataset.id = task.id;

    const checkbox = document.createElement('input');
    ...
    const span = document.createElement('span');
    ...
    const deleteBtn = document.createElement('button');
    ...

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(deleteBtn);

    // Event listeners
    checkbox.addEventListener('change', () => {
      const updated = tasks.map(t => {
        if (t.id === task.id) return { ...t, completed: checkbox.checked };
        return t;
      });
      saveTasks(updated);
      renderTasks();
    });

    deleteBtn.addEventListener('click', () => {
      const updated = tasks.filter(t => t.id !== task.id);
      saveTasks(updated);
      renderTasks();
    });

    list.appendChild(li);
});

Thus tasks refers to the outer local variable defined earlier in renderTasks. The closure has that tasks array. So the event listeners will refer to that tasks, and we produce updated arrays.

